    def _base_metric_for_candidate(
        self,
        *,
        candidate_label: str,
        candidate_term: AnsatzTerm,
        precompiled_action: CompiledPolynomialAction | None = None,
    ) -> float:
        pending = self.cursor.pending_selection
        if pending is None:
            raise RuntimeError(
                "Candidate metric evaluation requires a pending round."
            )
        cache_key = str(candidate_label)
        cached = pending.phase3_base_metric_cache.get(cache_key)
        if cached is not None:
            return float(cached)
        if (
            precompiled_action is not None
            and cache_key
            not in self.context.phase2_compiled_term_cache
        ):
            self.context.phase2_compiled_term_cache[cache_key] = (
                precompiled_action
            )
        metric = float(
            raw_f_metric_from_state(
                psi_state=np.asarray(
                    pending.psi_current,
                    dtype=complex,
                ),
                candidate_label=cache_key,
                candidate_term=candidate_term,
                compiled_cache=(
                    self.context.phase2_compiled_term_cache
                ),
                pauli_action_cache=self.cursor.pauli_action_cache,
            )
        )
        pending.phase3_base_metric_cache[cache_key] = metric
        return metric

