            controller_snapshot=controller_snapshot,
            selected_ops=self.cursor.selected_ops,
            theta_logical_current=pending.theta_logical_current,
            psi_current=pending.psi_current,
            reference_state=self.context.reference_state,
            compiled_hamiltonian=self.context.compiled_hamiltonian,
            pauli_action_cache=self.cursor.pauli_action_cache,
            phase2_score_cfg_round=pending.phase2_score_cfg_round,
            route_a_round_trust_snapshot=(
                pending.route_a_round_trust_snapshot
            ),
            coordinate_solve_policy=(
                self.context
                .historical_singleton_coordinate_solve_policy
            ),
            coordinate_scope=(
                self.context
                .historical_singleton_phase3_coordinate_scope
            ),
            trust_update_config=(
                self.context
                .historical_singleton_trust_update_config
            ),
            escape_mode=self.context.escape_mode,
            phase_shortlist_runtime=(
                self.context.phase_shortlist_runtime
            ),
